<template>
  <div v-if="loading" class="loading">
    <span>Загрузка...</span>
  </div>

  <div v-else-if="fund" class="fund">
    <!-- Header -->
    <div class="fund__header">
      <button class="fund__back" @click="router.back()">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <path d="M15 19L8 12L15 5" stroke="#111D33" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </button>
      <span class="fund__header-title">{{ fund.shortName }}</span>
      <div style="width:24px"/>
    </div>

    <!-- Hero Image (hero_url — широкий баннер) -->
    <div class="fund__hero">
      <img :src="fund.hero" :alt="fund.name" class="fund__hero-img" />
    </div>

    <!-- Content -->
    <div class="fund__content">
      <!-- Логотип фонда (logo_url — как в карточке списка) -->

      <h1 class="fund__name">{{ fund.name }}</h1>
      <p class="fund__desc">{{ fund.description }}</p>

      <!-- Mission -->
      <div v-if="fund.missionBlocks?.length" class="fund__mission">
        <h2 class="fund__mission-title">Миссия фонда</h2>
        <template v-for="(block, i) in fund.missionBlocks" :key="i">
          <ul v-if="block.type === 'list'" class="fund__list">
            <li v-for="(item, j) in block.items" :key="j" class="fund__list-item">{{ item }}</li>
          </ul>
          <p v-else class="fund__mission-text">{{ block.text }}</p>
        </template>
      </div>

      <!-- Illustration -->
      <div class="fund__illustration">
      <svg width="343" height="220" viewBox="0 0 343 220" fill="none" xmlns="http://www.w3.org/2000/svg">
