<script setup>
import { ref, onMounted } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { supabase } from '../services/supabase'
import BottomNav from '../components/BottomNav.vue'

const router = useRouter()
const route = useRoute()
const fund = ref(null)
const loading = ref(true)

function parseMission(text) {
  if (!text) return []
  const blocks = []
  let currentList = null

  const lines = text.split('\n')
  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed) continue

    if (trimmed.startsWith('•') || trimmed.startsWith('*') || trimmed.startsWith('-')) {
      const item = trimmed.replace(/^[•*-]\s*/, '')
      if (!currentList) {
        currentList = { type: 'list', items: [] }
        blocks.push(currentList)
      }
      currentList.items.push(item)
    } else {
      currentList = null
      blocks.push({ type: 'text', text: trimmed })
    }
  }

  return blocks
}

onMounted(async () => {
  const { data, error } = await supabase
    .from('funds')
    .select('*')
    .eq('id', route.params.id)
    .single()

  if (!error && data) {
    fund.value = {
      ...data,
      logo: data.logo_url,       // маленький логотип — как в fund-card__logo-wrap
      hero: data.hero_url,       // широкий баннер — только на странице фонда
      shortName: data.name
        .replace('Общественный благотворительный фонд ', '')
        .replace(/«|»/g, ''),
      missionBlocks: parseMission(data.mission),
    }
  }

  loading.value = false
})
</script>

